# Generated by packaging/homebrew/render.py in Gilfeather/furnace on each release; edits here are
# overwritten.
class Furnace < Formula
  desc "Inference server for Burn and ONNX models, speaking the KServe / Triton protocol"
  homepage "https://github.com/Gilfeather/furnace"
  version "0.9.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/Gilfeather/furnace/releases/download/v0.9.0/furnace-macos-aarch64"
      sha256 "8e4443f054b7f0939056eb16b05136a5123f75f26d4fdc660ce0409bbc048a97"
    end
    on_intel do
      url "https://github.com/Gilfeather/furnace/releases/download/v0.9.0/furnace-macos-x86_64"
      sha256 "4fd1e32bcf7ae358cdb840bfd38711d6351e4dc2a4fb9e8919e095ffcb85d544"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/Gilfeather/furnace/releases/download/v0.9.0/furnace-linux-aarch64"
      sha256 "61cbd4c03a73438fd7081932ce487fc3187ceb066c87494d3e7d91d2212e75c2"
    end
    on_intel do
      url "https://github.com/Gilfeather/furnace/releases/download/v0.9.0/furnace-linux-x86_64"
      sha256 "27485c6c626d60bbe0db1b4ca8cc09d0ba3ffeea6023cccaca8343f8146d173d"
    end
  end

  # Weights of the built-in ResNet-18, found next to the binary
  resource "resnet18-weights" do
    url "https://github.com/Gilfeather/furnace/releases/download/v0.9.0/resnet18.bpk"
    sha256 "c70f786275827582462948bd7810cb355e3a13c0d185dbf6ae5e369558e1a6d0"
  end

  def install
    # The binary and its weights stay together in libexec; bin gets a launcher
    libexec.install Dir["furnace-*"].first => "furnace"
    # A release asset is the bare binary, downloaded without the executable bit
    chmod 0755, libexec/"furnace"
    resource("resnet18-weights").stage { libexec.install "resnet18.bpk" }
    bin.write_exec_script libexec/"furnace"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/furnace --version")
  end
end
